def pack(comps, H,W):
 moved=True
 while moved:
  moved=False
  comps.sort(key=lambda x:max(c for r,c in x[1]),reverse=True)
  occ={(r,c):i for i,(_,cells) in enumerate(comps) for r,c in cells}
  for i,(color,cells) in enumerate(comps):
   if all(c+1<W and ((r,c+1) not in occ or occ[(r,c+1)]==i) for r,c in cells):
